sys_relationship.query_with:
(function refineQuery(current, parent) {
    if (parent.cmdb_ci.nil() || parent.start_date.nil() || parent.end_date.nil()) {
        current.addNullQuery('sys_id');
        return;
    }

    var assetGr = new GlideRecord('x_2223823_apollo_0_medical_equipment_assets');
    assetGr.addQuery('ci', parent.cmdb_ci);
    assetGr.setLimit(1);
    assetGr.query();
    if (!assetGr.next()) {
        current.addNullQuery('sys_id');
        return;
    }

    current.addQuery('equipment', assetGr.getUniqueValue());
    current.addQuery('scheduled_start', '<', parent.end_date);
    current.addQuery('scheduled_end', '>', parent.start_date);
	current.addEncodedQuery('statusNOT IN1,7,8,9,10');
})(current, parent);
